CREATE SCHEMA dev_meta;
SET SCHEMA dev_meta;

-- BEGIN V1__source_schema.sql
SET SCHEMA public;
-- Generated from reviewed website SQL by tools/generate-h2-schema.py.
-- Structural development mirror: no website accounts, orders, RLS, functions or triggers.
CREATE SEQUENCE IF NOT EXISTS public.customers_id_seq START WITH 1;

CREATE TABLE IF NOT EXISTS public.customers (
                                                id              bigint NOT NULL DEFAULT nextval('public.customers_id_seq'),
                                                phone1          varchar(20),
                                                phone2          varchar(20),
                                                email           varchar(255),
                                                house_number    varchar(50),
                                                street          varchar(255),
                                                area            varchar(255),
                                                complex_name    varchar(255),
                                                last_ordered_at timestamp without time zone,
                                                preferred_store text,
                                                city            varchar(255),
                                                password        varchar(255),
                                                postal_code     varchar(255),
                                                google_place_id varchar(255),
                                                formatted_address text,
                                                latitude        numeric(9,6),
                                                longitude       numeric(10,6),
                                                province        varchar(120),
                                                country         varchar(120),
                                                first_name      varchar(255),
                                                last_name       varchar(255),
                                                role            varchar(255) NOT NULL DEFAULT 'USER',
                                                access_level    smallint NOT NULL DEFAULT 0,
                                                environment_admin boolean NOT NULL DEFAULT false,

                                                CONSTRAINT customers_pkey PRIMARY KEY (id),
                                                CONSTRAINT customers_email_key UNIQUE (email),
                                                CONSTRAINT unique_phone1 UNIQUE (phone1)
);

CREATE TABLE IF NOT EXISTS public.customer_notes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id bigint NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
    author_username varchar(255) NOT NULL,
    body text NOT NULL CHECK (length(btrim(body)) BETWEEN 1 AND 2000),
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.password_reset_tokens (
                                                            id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                                            customer_id BIGINT NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
                                                            token_hash  VARCHAR(64) NOT NULL,
                                                            expires_at  TIMESTAMP WITHOUT TIME ZONE NOT NULL,
                                                            used        BOOLEAN NOT NULL DEFAULT FALSE,
                                                            created_at  TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.staff (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    branch      VARCHAR(255) NOT NULL,
    pin_hash    VARCHAR(255) NOT NULL,
    branch_code VARCHAR(16)
);

CREATE TABLE IF NOT EXISTS branch (
                                      branch_id INT PRIMARY KEY,
                                      name      TEXT NOT NULL UNIQUE,
                                      active    BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS menu_category (
                                             id         INT PRIMARY KEY,
                                             name       TEXT NOT NULL UNIQUE,
                                             sort_order INT NOT NULL DEFAULT 0,
                                             active     BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS menu_item (
                                         id          INT PRIMARY KEY,
                                         category_id INT NOT NULL REFERENCES menu_category(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                         name        TEXT NOT NULL,
                                         description TEXT,
                                         active      BOOLEAN NOT NULL DEFAULT TRUE,
                                         sort_order  INT NOT NULL DEFAULT 0,
                                         is_300ml    BOOLEAN NOT NULL DEFAULT FALSE,
                                         is_2l       BOOLEAN NOT NULL DEFAULT FALSE,
                                         UNIQUE (category_id, name)
);

CREATE TABLE IF NOT EXISTS branch_menu_item_price (
                                                      branch_id    INT NOT NULL REFERENCES branch(branch_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                      menu_item_id INT NOT NULL REFERENCES menu_item(id)     ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                      price        DOUBLE PRECISION NOT NULL CHECK (price >= 0),
                                                      PRIMARY KEY (branch_id, menu_item_id)
);

CREATE TABLE IF NOT EXISTS modifier_group (
                                              id         INT PRIMARY KEY,
                                              name       TEXT NOT NULL UNIQUE,
                                              required   BOOLEAN NOT NULL DEFAULT FALSE,
                                              min_select INT NOT NULL DEFAULT 0,
                                              max_select INT NOT NULL DEFAULT 1,
                                              CONSTRAINT chk_modifier_group_selection CHECK (
                                                  min_select >= 0 AND max_select >= min_select
                                                  )
);

CREATE TABLE IF NOT EXISTS modifier_option (
                                               id           INT PRIMARY KEY,
                                               group_id     INT NOT NULL REFERENCES modifier_group(id) ON DELETE CASCADE,
                                               name         TEXT NOT NULL,
                                               menu_item_id INT REFERENCES menu_item(id) ON DELETE SET NULL,
                                               additional_price NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (additional_price >= 0),
                                               UNIQUE (group_id, name)
);

CREATE TABLE IF NOT EXISTS menu_item_modifier_group (
                                                        menu_item_id INT NOT NULL REFERENCES menu_item(id) ON DELETE CASCADE,
                                                        group_id     INT NOT NULL REFERENCES modifier_group(id) ON DELETE CASCADE,
                                                        PRIMARY KEY (menu_item_id, group_id)
);

CREATE TABLE IF NOT EXISTS burger_component (
                                                component_id   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                                name           TEXT NOT NULL UNIQUE,
                                                component_type TEXT NOT NULL CHECK (
                                                    component_type IN ('default_topping', 'protein', 'extra_topping')
                                                    ),
                                                active         BOOLEAN NOT NULL DEFAULT TRUE,
                                                seasonal       BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS burger_recipe (
                                             recipe_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                             name      TEXT NOT NULL UNIQUE,
                                             active    BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS burger_recipe_component (
                                                       recipe_id     INT NOT NULL REFERENCES burger_recipe(recipe_id) ON DELETE CASCADE,
                                                       component_id  INT NOT NULL REFERENCES burger_component(component_id) ON DELETE RESTRICT,
                                                       is_removable  BOOLEAN NOT NULL DEFAULT TRUE,
                                                       sort_order    INT NOT NULL DEFAULT 0,
                                                       PRIMARY KEY (recipe_id, component_id)
);

CREATE TABLE IF NOT EXISTS burger_recipe_assignment (
                                                        burger_id                   INT PRIMARY KEY REFERENCES menu_item(id) ON DELETE CASCADE,
                                                        recipe_id                   INT NOT NULL REFERENCES burger_recipe(recipe_id) ON DELETE RESTRICT,
                                                        protein_quantity_required   INT NOT NULL DEFAULT 1 CHECK (protein_quantity_required > 0),
                                                        protein_required            BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS burger_item_default_component (
                                                             burger_id      INT NOT NULL REFERENCES menu_item(id) ON DELETE CASCADE,
                                                             component_id   INT NOT NULL REFERENCES burger_component(component_id) ON DELETE RESTRICT,
                                                             is_removable   BOOLEAN NOT NULL DEFAULT TRUE,
                                                             sort_order     INT NOT NULL DEFAULT 100,
                                                             PRIMARY KEY (burger_id, component_id)
);

CREATE TABLE IF NOT EXISTS branch_burger_component_price (
                                                             branch_id     INT NOT NULL REFERENCES branch(branch_id) ON DELETE CASCADE,
                                                             component_id  INT NOT NULL REFERENCES burger_component(component_id) ON DELETE CASCADE,
                                                             price         NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (price >= 0),
                                                             PRIMARY KEY (branch_id, component_id)
);

CREATE TABLE IF NOT EXISTS salad_ingredients (
                                                 id              INT PRIMARY KEY,
                                                 salad_id        INT NOT NULL REFERENCES menu_item(id) ON UPDATE RESTRICT ON DELETE CASCADE,
                                                 ingredient_name TEXT NOT NULL,
                                                 price           DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (price >= 0),
                                                 UNIQUE (salad_id, ingredient_name)
);

CREATE TABLE IF NOT EXISTS pizza_category (
                                              pizza_category_id INT PRIMARY KEY,
                                              name              TEXT NOT NULL UNIQUE,
                                              sort_order        INT NOT NULL DEFAULT 0,
                                              active            BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS pizza (
                                     pizza_id          INT PRIMARY KEY,
                                     pizza_category_id INT NOT NULL REFERENCES pizza_category(pizza_category_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                     name              TEXT NOT NULL,
                                     description       TEXT,
                                     sort_order        INT NOT NULL DEFAULT 0,
                                     active            BOOLEAN NOT NULL DEFAULT TRUE,
                                     CONSTRAINT uq_pizza_name UNIQUE (pizza_category_id, name)
);

CREATE TABLE IF NOT EXISTS pizza_size (
                                          pizza_size_id INT PRIMARY KEY,
                                          cm            INT NOT NULL UNIQUE,
                                          sort_order    INT NOT NULL DEFAULT 0,
                                          active        BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS pizza_allowed_size (
                                                  pizza_id      INT NOT NULL REFERENCES pizza(pizza_id) ON DELETE CASCADE,
                                                  pizza_size_id INT NOT NULL REFERENCES pizza_size(pizza_size_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                  PRIMARY KEY (pizza_id, pizza_size_id)
);

CREATE TABLE IF NOT EXISTS price_category (
                                              price_category_id INT PRIMARY KEY,
                                              name              TEXT NOT NULL UNIQUE,
                                              sort_order        INT NOT NULL DEFAULT 0,
                                              active            BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS ingredient (
                                          ingredient_id     INT PRIMARY KEY,
                                          name              TEXT NOT NULL UNIQUE,
                                          price_category_id INT NOT NULL REFERENCES price_category(price_category_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                          active            BOOLEAN NOT NULL DEFAULT TRUE,
                                          seasonal          BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS pizza_default_ingredient (
                                                        pizza_id      INT NOT NULL REFERENCES pizza(pizza_id) ON DELETE CASCADE,
                                                        ingredient_id INT NOT NULL REFERENCES ingredient(ingredient_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                        is_removable  BOOLEAN NOT NULL DEFAULT TRUE,
                                                        default_qty   INT NOT NULL DEFAULT 1 CHECK (default_qty > 0),
                                                        sort_order    INT NOT NULL DEFAULT 0,
                                                        PRIMARY KEY (pizza_id, ingredient_id)
);

CREATE TABLE IF NOT EXISTS branch_pizza_price (
                                                  branch_id     INT NOT NULL REFERENCES branch(branch_id) ON DELETE CASCADE,
                                                  pizza_id      INT NOT NULL REFERENCES pizza(pizza_id) ON DELETE CASCADE,
                                                  pizza_size_id INT NOT NULL REFERENCES pizza_size(pizza_size_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                  price         DOUBLE PRECISION NOT NULL CHECK (price >= 0),
                                                  PRIMARY KEY (branch_id, pizza_id, pizza_size_id)
);

CREATE TABLE IF NOT EXISTS branch_extra_price (
                                                  branch_id         INT NOT NULL REFERENCES branch(branch_id) ON DELETE CASCADE,
                                                  price_category_id INT NOT NULL REFERENCES price_category(price_category_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                  pizza_size_id     INT NOT NULL REFERENCES pizza_size(pizza_size_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                  price             DOUBLE PRECISION NOT NULL CHECK (price >= 0),
                                                  PRIMARY KEY (branch_id, price_category_id, pizza_size_id)
);

CREATE TABLE IF NOT EXISTS pizza_base_option (
                                                 pizza_base_option_id INT PRIMARY KEY,
                                                 name                 TEXT NOT NULL UNIQUE,
                                                 active               BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS branch_pizza_base_option_price (
                                                              branch_id            INT NOT NULL REFERENCES branch(branch_id) ON DELETE CASCADE,
                                                              pizza_base_option_id INT NOT NULL REFERENCES pizza_base_option(pizza_base_option_id) ON DELETE CASCADE,
                                                              pizza_size_id        INT NOT NULL REFERENCES pizza_size(pizza_size_id) ON DELETE CASCADE,
                                                              price                DOUBLE PRECISION NOT NULL CHECK (price >= 0),
                                                              PRIMARY KEY (branch_id, pizza_base_option_id, pizza_size_id)
);

CREATE TABLE IF NOT EXISTS customer_order (
                                              order_id     BIGSERIAL PRIMARY KEY,
                                              branch_id    INT NOT NULL REFERENCES branch(branch_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                              customer_id  BIGINT REFERENCES public.customers(id) ON UPDATE RESTRICT ON DELETE SET NULL,

                                              order_type   TEXT NOT NULL DEFAULT 'pickup',
                                              status       TEXT NOT NULL DEFAULT 'created',
                                              created_at   TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,


                                              customer_name TEXT,
                                              phone          TEXT,
                                              house_number   VARCHAR(255),
                                              street         VARCHAR(255),
                                              area           VARCHAR(255),
                                              city           VARCHAR(255),
                                              postal_code    VARCHAR(255),
                                              complex_name   VARCHAR(255),
                                              google_place_id VARCHAR(255),
                                              formatted_address TEXT,
                                              latitude NUMERIC(9,6),
                                              longitude NUMERIC(10,6),
                                              province VARCHAR(120),
                                              country VARCHAR(120),
                                              gate_access_code VARCHAR(64),
                                              notes          TEXT
);

CREATE TABLE IF NOT EXISTS order_menu_item (
                                               order_menu_item_id BIGSERIAL PRIMARY KEY,
                                               order_id           BIGINT NOT NULL REFERENCES customer_order(order_id) ON DELETE CASCADE,
                                               menu_item_id       INT NOT NULL REFERENCES menu_item(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                               qty                INT NOT NULL DEFAULT 1 CHECK (qty > 0),
                                               unit_price_at_time DOUBLE PRECISION NOT NULL CHECK (unit_price_at_time >= 0),
                                               item_name_at_time  TEXT,
                                               notes              TEXT
);

CREATE TABLE IF NOT EXISTS order_menu_item_extra (
                                                     order_menu_item_extra_id BIGSERIAL PRIMARY KEY,
                                                     order_menu_item_id       BIGINT NOT NULL REFERENCES order_menu_item(order_menu_item_id) ON DELETE CASCADE,
                                                     name                     TEXT NOT NULL,
                                                     qty                      INT NOT NULL DEFAULT 1 CHECK (qty > 0),
                                                     unit_price_at_time       DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (unit_price_at_time >= 0)
);

CREATE TABLE IF NOT EXISTS order_burger_protein (
                                                    order_menu_item_id       BIGINT PRIMARY KEY
                                                        REFERENCES order_menu_item(order_menu_item_id) ON DELETE CASCADE,
                                                    component_id             INT NOT NULL
                                                        REFERENCES burger_component(component_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                    protein_qty_per_burger   INT NOT NULL CHECK (protein_qty_per_burger > 0),
                                                    unit_price_at_time       NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (unit_price_at_time >= 0)
);

CREATE TABLE IF NOT EXISTS order_burger_removed_component (
                                                              order_menu_item_id BIGINT NOT NULL
                                                                  REFERENCES order_menu_item(order_menu_item_id) ON DELETE CASCADE,
                                                              component_id       INT NOT NULL
                                                                  REFERENCES burger_component(component_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                              PRIMARY KEY (order_menu_item_id, component_id)
);

CREATE TABLE IF NOT EXISTS order_burger_extra_component (
                                                            order_menu_item_id BIGINT NOT NULL
                                                                REFERENCES order_menu_item(order_menu_item_id) ON DELETE CASCADE,
                                                            component_id       INT NOT NULL
                                                                REFERENCES burger_component(component_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                            qty                INT NOT NULL DEFAULT 1 CHECK (qty > 0),
                                                            unit_price_at_time NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (unit_price_at_time >= 0),
                                                            PRIMARY KEY (order_menu_item_id, component_id)
);

CREATE TABLE IF NOT EXISTS order_pizza_item (
                                                order_pizza_item_id  BIGSERIAL PRIMARY KEY,
                                                order_id             BIGINT NOT NULL REFERENCES customer_order(order_id) ON DELETE CASCADE,
                                                pizza_id             INT NOT NULL REFERENCES pizza(pizza_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                pizza_size_id        INT NOT NULL REFERENCES pizza_size(pizza_size_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                qty                  INT NOT NULL DEFAULT 1 CHECK (qty > 0),
                                                base_price_at_time   DOUBLE PRECISION NOT NULL CHECK (base_price_at_time >= 0),
                                                notes                TEXT
);

CREATE TABLE IF NOT EXISTS order_pizza_item_extra (
                                                      order_pizza_item_extra_id BIGSERIAL PRIMARY KEY,
                                                      order_pizza_item_id       BIGINT NOT NULL REFERENCES order_pizza_item(order_pizza_item_id) ON DELETE CASCADE,
                                                      ingredient_id             INT NOT NULL REFERENCES ingredient(ingredient_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                      qty                       INT NOT NULL DEFAULT 1 CHECK (qty > 0),
                                                      unit_price_at_time        DOUBLE PRECISION NOT NULL CHECK (unit_price_at_time >= 0)
);

CREATE TABLE IF NOT EXISTS order_pizza_item_base_option (
                                                            order_pizza_item_id  BIGINT PRIMARY KEY REFERENCES order_pizza_item(order_pizza_item_id) ON DELETE CASCADE,
                                                            pizza_base_option_id INT NOT NULL REFERENCES pizza_base_option(pizza_base_option_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
                                                            unit_price_at_time   DOUBLE PRECISION NOT NULL CHECK (unit_price_at_time >= 0)
);

CREATE TABLE IF NOT EXISTS special (
    special_id BIGSERIAL PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    branch_id INT NOT NULL REFERENCES branch(branch_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    name TEXT NOT NULL,
    description TEXT,
    bundle_price NUMERIC(10,2) NOT NULL CHECK (bundle_price >= 0),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    archived BOOLEAN NOT NULL DEFAULT FALSE,
    starts_on DATE,
    ends_on DATE,
    sort_order INT NOT NULL DEFAULT 0,
    CONSTRAINT chk_special_date_range CHECK (starts_on IS NULL OR ends_on IS NULL OR starts_on <= ends_on)
);

CREATE TABLE IF NOT EXISTS special_day (
    special_id BIGINT NOT NULL REFERENCES special(special_id) ON DELETE CASCADE,
    day_of_week INT NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),
    PRIMARY KEY (special_id, day_of_week)
);

CREATE TABLE IF NOT EXISTS special_component (
    special_component_id BIGSERIAL PRIMARY KEY,
    special_id BIGINT NOT NULL REFERENCES special(special_id) ON DELETE CASCADE,
    component_code TEXT NOT NULL,
    label TEXT NOT NULL,
    product_type TEXT NOT NULL CHECK (product_type IN ('MENU_ITEM', 'PIZZA')),
    quantity INT NOT NULL CHECK (quantity > 0),
    selection_mode TEXT NOT NULL CHECK (selection_mode IN ('INCLUDED', 'CUSTOMER_CHOICE')),
    menu_category_id INT REFERENCES menu_category(id) ON DELETE RESTRICT,
    pizza_category_id INT REFERENCES pizza_category(pizza_category_id) ON DELETE RESTRICT,
    pizza_size_id INT REFERENCES pizza_size(pizza_size_id) ON DELETE RESTRICT,
    allow_repeats BOOLEAN NOT NULL DEFAULT FALSE,
    allow_customization BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order INT NOT NULL DEFAULT 0,
    UNIQUE (special_id, component_code),
    CONSTRAINT chk_special_component_category CHECK (
        (product_type = 'MENU_ITEM' AND pizza_category_id IS NULL AND pizza_size_id IS NULL)
        OR (product_type = 'PIZZA' AND menu_category_id IS NULL)
    )
);

CREATE TABLE IF NOT EXISTS special_component_menu_item (
    special_component_id BIGINT NOT NULL REFERENCES special_component(special_component_id) ON DELETE CASCADE,
    menu_item_id INT NOT NULL REFERENCES menu_item(id) ON DELETE RESTRICT,
    PRIMARY KEY (special_component_id, menu_item_id)
);

CREATE TABLE IF NOT EXISTS special_component_pizza (
    special_component_id BIGINT NOT NULL REFERENCES special_component(special_component_id) ON DELETE CASCADE,
    pizza_id INT NOT NULL REFERENCES pizza(pizza_id) ON DELETE RESTRICT,
    PRIMARY KEY (special_component_id, pizza_id)
);

CREATE TABLE IF NOT EXISTS special_addon (
    special_addon_id BIGSERIAL PRIMARY KEY,
    special_id BIGINT NOT NULL REFERENCES special(special_id) ON DELETE CASCADE,
    addon_code TEXT NOT NULL,
    label TEXT NOT NULL,
    product_type TEXT NOT NULL CHECK (product_type IN ('MENU_ITEM', 'PIZZA')),
    menu_item_id INT REFERENCES menu_item(id) ON DELETE RESTRICT,
    pizza_id INT REFERENCES pizza(pizza_id) ON DELETE RESTRICT,
    pizza_size_id INT REFERENCES pizza_size(pizza_size_id) ON DELETE RESTRICT,
    price NUMERIC(10,2) NOT NULL CHECK (price >= 0),
    max_quantity INT NOT NULL DEFAULT 1 CHECK (max_quantity > 0),
    allow_customization BOOLEAN NOT NULL DEFAULT TRUE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order INT NOT NULL DEFAULT 0,
    UNIQUE (special_id, addon_code),
    CONSTRAINT chk_special_addon_product CHECK (
        (product_type = 'MENU_ITEM' AND menu_item_id IS NOT NULL AND pizza_id IS NULL AND pizza_size_id IS NULL)
        OR (product_type = 'PIZZA' AND pizza_id IS NOT NULL AND menu_item_id IS NULL AND pizza_size_id IS NOT NULL)
    )
);

CREATE TABLE IF NOT EXISTS order_special_item (
    order_special_item_id BIGSERIAL PRIMARY KEY,
    order_id BIGINT NOT NULL REFERENCES customer_order(order_id) ON DELETE CASCADE,
    special_id BIGINT REFERENCES special(special_id) ON DELETE SET NULL,
    special_name_at_time TEXT NOT NULL,
    special_description_at_time TEXT,
    quantity INT NOT NULL DEFAULT 1 CHECK (quantity > 0),
    base_price_at_time NUMERIC(10,2) NOT NULL CHECK (base_price_at_time >= 0),
    customization_total_at_time NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (customization_total_at_time >= 0),
    addon_total_at_time NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (addon_total_at_time >= 0),
    final_line_total_at_time NUMERIC(10,2) NOT NULL CHECK (final_line_total_at_time >= 0)
);

CREATE TABLE IF NOT EXISTS order_special_selection (
    order_special_selection_id BIGSERIAL PRIMARY KEY,
    order_special_item_id BIGINT NOT NULL REFERENCES order_special_item(order_special_item_id) ON DELETE CASCADE,
    selection_kind TEXT NOT NULL CHECK (selection_kind IN ('COMPONENT', 'ADDON')),
    special_component_id BIGINT REFERENCES special_component(special_component_id) ON DELETE SET NULL,
    special_addon_id BIGINT REFERENCES special_addon(special_addon_id) ON DELETE SET NULL,
    selection_index INT NOT NULL DEFAULT 1 CHECK (selection_index > 0),
    label_at_time TEXT NOT NULL,
    product_name_at_time TEXT NOT NULL,
    pizza_size_cm_at_time INT,
    selection_quantity INT NOT NULL DEFAULT 1 CHECK (selection_quantity > 0),
    addon_price_at_time NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (addon_price_at_time >= 0),
    customization_charge_at_time NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (customization_charge_at_time >= 0),
    order_menu_item_id BIGINT REFERENCES order_menu_item(order_menu_item_id) ON DELETE CASCADE,
    order_pizza_item_id BIGINT REFERENCES order_pizza_item(order_pizza_item_id) ON DELETE CASCADE,
    CONSTRAINT chk_order_special_selection_source CHECK (
        (selection_kind = 'COMPONENT' AND special_addon_id IS NULL)
        OR (selection_kind = 'ADDON' AND special_component_id IS NULL)
    ),
    CONSTRAINT chk_order_special_selection_item CHECK (
        (order_menu_item_id IS NOT NULL AND order_pizza_item_id IS NULL)
        OR (order_menu_item_id IS NULL AND order_pizza_item_id IS NOT NULL)
    )
);

CREATE TABLE IF NOT EXISTS order_pizza_item_removed_ingredient (
    order_pizza_item_id BIGINT NOT NULL REFERENCES order_pizza_item(order_pizza_item_id) ON DELETE CASCADE,
    ingredient_id INT NOT NULL REFERENCES ingredient(ingredient_id) ON DELETE RESTRICT,
    ingredient_name_at_time TEXT NOT NULL,
    PRIMARY KEY (order_pizza_item_id, ingredient_id)
);

CREATE TABLE IF NOT EXISTS public.driver_profile (
    driver_id bigint PRIMARY KEY REFERENCES public.customers(id) ON DELETE RESTRICT,
    branch_id integer NOT NULL REFERENCES public.branch(branch_id),
    hourly_rate numeric(10,2) NOT NULL DEFAULT 0 CHECK (hourly_rate >= 0),
    per_delivery_rate numeric(10,2) NOT NULL DEFAULT 0 CHECK (per_delivery_rate >= 0),
    active boolean NOT NULL DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.driver_shift (
    shift_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    driver_id bigint NOT NULL REFERENCES public.driver_profile(driver_id),
    branch_id integer NOT NULL REFERENCES public.branch(branch_id),
    business_date date NOT NULL,
    clocked_in_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    clocked_out_at TIMESTAMP WITH TIME ZONE,
    approved_minutes integer CHECK (approved_minutes >= 0),
    hourly_rate numeric(10,2) NOT NULL CHECK (hourly_rate >= 0),
    per_delivery_rate numeric(10,2) NOT NULL CHECK (per_delivery_rate >= 0),
    returning_at TIMESTAMP WITH TIME ZONE,
    state text NOT NULL DEFAULT 'ACTIVE' CHECK (state IN ('ACTIVE', 'CLOCKED_OUT', 'SETTLED'))
);

CREATE TABLE IF NOT EXISTS public.delivery_assignment (
    assignment_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id bigint NOT NULL UNIQUE REFERENCES public.customer_order(order_id) ON DELETE RESTRICT,
    driver_id bigint NOT NULL REFERENCES public.driver_profile(driver_id),
    shift_id bigint NOT NULL REFERENCES public.driver_shift(shift_id),
    branch_id integer NOT NULL REFERENCES public.branch(branch_id),
    assigned_by bigint REFERENCES public.customers(id),
    self_claimed boolean NOT NULL DEFAULT false,
    state text NOT NULL DEFAULT 'ASSIGNED' CHECK (state IN ('ASSIGNED', 'PICKED_UP', 'DELIVERED', 'CANCELLED')),
    assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    picked_up_at TIMESTAMP WITH TIME ZONE,
    delivered_at TIMESTAMP WITH TIME ZONE
);

CREATE TABLE IF NOT EXISTS public.driver_dispatch_event (
    event_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shift_id bigint NOT NULL REFERENCES public.driver_shift(shift_id),
    assignment_id bigint REFERENCES public.delivery_assignment(assignment_id),
    actor_id bigint REFERENCES public.customers(id),
    actor_username varchar(255) NOT NULL,
    branch_id integer NOT NULL REFERENCES public.branch(branch_id),
    event_type varchar(40) NOT NULL,
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.delivery_payment (
    order_id bigint PRIMARY KEY REFERENCES public.customer_order(order_id) ON DELETE RESTRICT,
    method text NOT NULL CHECK (method IN ('CASH', 'ONLINE')),
    online_order_paid numeric(12,2) NOT NULL DEFAULT 0 CHECK (online_order_paid >= 0),
    online_tip numeric(12,2) NOT NULL DEFAULT 0 CHECK (online_tip >= 0),
    cash_tip numeric(12,2) NOT NULL DEFAULT 0 CHECK (cash_tip >= 0),
    provider_reference text,
    verified_at TIMESTAMP WITH TIME ZONE,
    CHECK ((method = 'CASH' AND online_order_paid = 0 AND online_tip = 0)
        OR (method = 'ONLINE' AND cash_tip = 0 AND verified_at IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS public.driver_settlement (
    settlement_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shift_id bigint NOT NULL UNIQUE REFERENCES public.driver_shift(shift_id),
    driver_id bigint NOT NULL REFERENCES public.driver_profile(driver_id),
    branch_id integer NOT NULL REFERENCES public.branch(branch_id),
    manager_id bigint REFERENCES public.customers(id),
    manager_username varchar(255) NOT NULL,
    order_sales numeric(12,2) NOT NULL,
    online_order_paid numeric(12,2) NOT NULL DEFAULT 0,
    online_tips numeric(12,2) NOT NULL DEFAULT 0,
    cash_tips numeric(12,2) NOT NULL DEFAULT 0,
    hourly_pay numeric(12,2) NOT NULL,
    delivery_pay numeric(12,2) NOT NULL,
    expected_cash_due numeric(12,2) NOT NULL,
    cash_handed_in numeric(12,2) NOT NULL DEFAULT 0 CHECK (cash_handed_in >= 0),
    cash_paid_out numeric(12,2) NOT NULL DEFAULT 0 CHECK (cash_paid_out >= 0),
    variance numeric(12,2) NOT NULL,
    variance_reason text,
    settled_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

