 default_qty INT NOT NULL DEFAULT 1 CHECK(default_qty>0),
 is_removable BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0,
 PRIMARY KEY(menu_item_id,ingredient_id)
);
